type AppEnv={Bindings:Env;Variables:{requestId:string}};
export const api=new Hono<AppEnv>();
const parse=<T>(schema:{parse:(value:unknown)=>T},value:unknown)=>schema.parse(value);

api.use('*',async(c,next)=>{const ok=await checkRate(c.env.DB,'primary',180,1);if(!ok)return c.json({error:'Rate limit exceeded. Try again shortly.'},429);await next();});

api.get('/me',async(c)=>{const user=await c.env.DB.prepare(`SELECT u.*,p.* FROM users u LEFT JOIN learner_profiles p ON p.user_id=u.id WHERE u.id=?`).bind(SINGLE_USER_ID).first();return c.json({user,needsBootstrap:!user,accessEmail:c.req.header('cf-access-authenticated-user-email')??null});});
api.get('/settings',async(c)=>{const profile=await c.env.DB.prepare('SELECT * FROM learner_profiles WHERE user_id=?').bind(SINGLE_USER_ID).first();const values=await c.env.DB.prepare('SELECT key,value_json FROM app_settings').all<{key:string;value_json:string}>();return c.json({profile,settings:Object.fromEntries(values.results.map((v)=>[v.key,json(v.value_json,{})]))});});
api.put('/settings',async(c)=>{const input=parse(settingsSchema,await c.req.json());if(input.dailyMinutes||input.scaffoldingLevel!==undefined)await c.env.DB.prepare(`UPDATE learner_profiles SET daily_minutes=COALESCE(?,daily_minutes),scaffolding_level=COALESCE(?,scaffolding_level),updated_at=CURRENT_TIMESTAMP WHERE user_id=?`).bind(input.dailyMinutes??null,input.scaffoldingLevel??null,SINGLE_USER_ID).run();if(input.audioRetentionDays!==undefined)await c.env.DB.prepare(`INSERT INTO app_settings(key,value_json) VALUES('audio_retention_days',?) ON CONFLICT(key) DO UPDATE SET value_json=excluded.value_json,updated_at=CURRENT_TIMESTAMP`).bind(JSON.stringify(input.audioRetentionDays)).run();if(input.dailyAiCallLimit!==undefined||input.monthlyAiBudgetUsd!==undefined){const row=await c.env.DB.prepare(`SELECT value_json FROM app_settings WHERE key='budget'`).first<{value_json:string}>();const budget=json(row?.value_json,{dailyAiCallLimit:60,dailyAudioMinuteSoftLimit:30,monthlyEstimatedCostAlert:25,strongModelCallsPerDay:6});if(input.dailyAiCallLimit!==undefined)budget.dailyAiCallLimit=input.dailyAiCallLimit;if(input.monthlyAiBudgetUsd!==undefined)budget.monthlyEstimatedCostAlert=input.monthlyAiBudgetUsd;await c.env.DB.prepare(`INSERT INTO app_settings(key,value_json) VALUES('budget',?) ON CONFLICT(key) DO UPDATE SET value_json=excluded.value_json,updated_at=CURRENT_TIMESTAMP`).bind(JSON.stringify(budget)).run();}return c.json({ok:true,input});});
api.post('/bootstrap',async(c)=>c.json(await bootstrapDatabase(c.env.DB)));
api.post('/provider-health-check',async(c)=>{const providers=createProviders(c.env);try{const result=await providers.text.generateText({taskType:'health',system:'Reply with OK.',prompt:'health check',modelRole:'daily_fast'});return c.json({ok:true,mode:providers.mode,provider:result.provider,model:result.model,ttsFallback:await providers.tts.synthesize('health')===null});}catch(error){return c.json({ok:false,mode:providers.mode,error:error instanceof Error?error.message:'Provider failed'},503);}});

api.post('/assessments',async(c)=>{const id=crypto.randomUUID();await c.env.DB.prepare(`INSERT INTO assessments(id,user_id,assessment_type,version) VALUES(?,'primary','adaptive_baseline',3)`).bind(id).run();const items=await buildAssessmentItems(c.env.DB,id);const sections=items.reduce<Record<string,number>>((counts,item)=>{counts[item.section]=(counts[item.section]??0)+1;return counts;},{});return c.json({id,sections,items,total:assessmentMachineSampleSize+4,currentTotal:items.length,scoring:'adaptive_machine',adaptive:{machineSampleSize:assessmentMachineSampleSize,rule:'B1/B2 routing from recent verified accuracy; balanced recognition and active recall'}},201);});
api.get('/assessments/:id',async(c)=>{const assessment=await c.env.DB.prepare('SELECT * FROM assessments WHERE id=? AND user_id=?').bind(c.req.param('id'),SINGLE_USER_ID).first();if(!assessment)return c.json({error:'Assessment not found'},404);const responses=await c.env.DB.prepare('SELECT * FROM assessment_responses WHERE assessment_id=? ORDER BY rowid').bind(c.req.param('id')).all();const items=await listAssessmentItems(c.env.DB,c.req.param('id'));return c.json({assessment,responses:responses.results,items});});
api.post('/assessments/:id/responses',async(c)=>{const input=parse(assessmentResponseSchema,await c.req.json());const scored=await machineScoreAssessmentItem(c.env.DB,c.req.param('id'),input.itemId,input.responseText??'',input.responseMs);if(!scored||scored.section!==input.section)return c.json({error:'Assessment item not found or section mismatch.'},404);const id=crypto.randomUUID();await c.env.DB.batch([c.env.DB.prepare(`DELETE FROM assessment_responses WHERE assessment_id=? AND item_id=?`).bind(c.req.param('id'),input.itemId),c.env.DB.prepare(`INSERT INTO assessment_responses(id,assessment_id,item_id,section,response_text,audio_object_key,correct,response_ms,replay_count,hint_level,evaluation_json,machine_score) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)`).bind(id,c.req.param('id'),input.itemId,input.section,input.responseText??null,input.audioKey??null,scored.correct===null?null:scored.correct?1:0,input.responseMs,input.replayCount,input.hintLevel,JSON.stringify(input.pronunciation??{}),scored.score)]);if(scored.unit_id&&scored.score!==null)await recordLearningEvidence(c.env.DB,{unitId:scored.unit_id,source:'assessment',dimension:scored.section==='receptive'?'recognition':'recall',score:scored.score,verified:true,responseText:input.responseText,responseMs:input.responseMs,metadata:{assessmentId:c.req.param('id'),itemId:input.itemId},activateCards:scored.score>=65});const nextItem=scored.score===null?null:await selectNextAssessmentItem(c.env.DB,c.req.param('id'));return c.json({id,correct:scored.correct,score:scored.score,nextItem},201);});
api.post('/assessments/:id/transcribe',async(c)=>{const form=await c.req.formData();const audio=form.get('audio');if(!(audio instanceof File))return c.json({error:'Audio file is required.'},400);if(audio.size>AUDIO_MAX_BYTES||!AUDIO_MIME_TYPES.includes(audio.type as typeof AUDIO_MIME_TYPES[number]))return c.json({error:'Unsupported or oversized audio. Maximum 12 MB.'},413);const referenceText=String(form.get('referenceText')??'').slice(0,2000);const audioKey=`audio/assessments/${c.req.param('id')}/${crypto.randomUUID()}`;await c.env.AUDIO_BUCKET.put(audioKey,audio.stream(),{httpMetadata:{contentType:audio.type},customMetadata:{retentionDays:c.env.AUDIO_RETENTION_DAYS}});const bytes=await audio.arrayBuffer();const transcript=await createProviders(c.env).stt.transcribe(bytes,audio.type);let pronunciation:unknown=undefined;if(referenceText&&(c.env.PRONUNCIATION_ASSESSMENT_ENABLED==='true'||c.env.PRONUNCIATION_ASSESSMENT_ENABLED==='1')){try{pronunciation=await assessPronunciation(c.env,bytes,audio.type,referenceText);}catch{/* optional provider failure never blocks STT */}}return c.json({audioKey,transcript:transcript.text,confidence:transcript.confidence??null,pronunciation});});
api.post('/assessments/:id/complete',async(c)=>{const rows=await c.env.DB.prepare('SELECT section,response_text,correct,machine_score,response_ms,hint_level FROM assessment_responses WHERE assessment_id=?').bind(c.req.param('id')).all<{section:string;response_text:string|null;correct:number|null;machine_score:number|null;response_ms:number;hint_level:number}>();const requiredRows=await c.env.DB.prepare('SELECT section,COUNT(*) count FROM assessment_items WHERE assessment_id=? GROUP BY section').bind(c.req.param('id')).all<{section:string;count:number}>();const bySection=rows.results.reduce<Record<string, typeof rows.results>>((acc,r)=>{(acc[r.section]??=[]).push(r);return acc;},{});const missing=requiredRows.results.filter(({section,count})=>(bySection[section]?.length??0)<count).map(({section,count})=>({section,required:count,completed:bySection[section]?.length??0}));if(missing.length)return c.json({error:'Complete every adaptive baseline item before scoring.',missing},400);const score=(name:string)=>{const list=(bySection[name]??[]).filter((row)=>row.machine_score!==null);return list.length?Math.round(list.reduce((n,r)=>n+Number(r.machine_score),0)/list.length):0;};const objective={receptive:score('receptive'),activeRecall:score('active_recall'),responses:rows.results.length,averageResponseMs:Math.round(rows.results.reduce((n,r)=>n+r.response_ms,0)/Math.max(rows.results.length,1)),machineScoredItems:(bySection.receptive?.length??0)+(bySection.active_recall?.length??0)};const freeResponses=rows.results.filter((row)=>['writing','speaking','listening'].includes(row.section)).map((row)=>({section:row.section,response:row.response_text}));const evaluator=await createProviders(c.env).text.generateStructured({taskType:'assessment',system:assessmentPrompt,prompt:JSON.stringify({objective,freeResponses,rubric:'fixed 1-5 analytic rubric; do not infer from learner self-rating'}),modelRole:'evaluator_strong',sensitive:true},assessmentEvaluationSchema);const productiveAverage=Math.round((objective.activeRecall+evaluator.writing*20+evaluator.speaking*20)/3);const working=objective.receptive>=85&&productiveAverage>=75?'B2+ working estimate':objective.receptive>=75&&productiveAverage>=60?'B2 working estimate':'B1+ / early B2 working estimate';const report={workingCefr:working,confidence:evaluator.confidence,receptiveVsActiveGap:objective.receptive-objective.activeRecall,vocabularyCategories:{generalB2:'machine-scored sample',commercialRealEstate:'machine-scored sample',negotiation:'machine-scored sample',analytical:'machine-scored sample'},topRecurringErrors:evaluator.topRecurringErrors,focus:evaluator.focus,disclaimer:'Adaptive working estimate based on machine-scored vocabulary and rubric-scored output; not an official CEFR certification.'};await c.env.DB.batch([c.env.DB.prepare(`UPDATE assessments SET completed_at=CURRENT_TIMESTAMP,objective_scores_json=?,evaluator_scores_json=?,working_cefr=?,report_json=? WHERE id=?`).bind(JSON.stringify(objective),JSON.stringify(evaluator),working,JSON.stringify(report),c.req.param('id')),c.env.DB.prepare(`UPDATE learner_profiles SET assessment_completed=1,working_cefr=? WHERE user_id='primary'`).bind(working)]);return c.json({objective,evaluator,report});});

api.get('/today',async(c)=>{const profile=await c.env.DB.prepare('SELECT timezone,daily_minutes FROM users u JOIN learner_profiles p ON p.user_id=u.id WHERE u.id=?').bind(SINGLE_USER_ID).first<{timezone:string;daily_minutes:number}>();if(!profile)return c.json({needsBootstrap:true},409);return c.json(await getToday(c.env.DB,profile.timezone,profile.daily_minutes));});
api.post('/today/generate',async(c)=>{const profile=await c.env.DB.prepare('SELECT timezone,daily_minutes FROM users u JOIN learner_profiles p ON p.user_id=u.id WHERE u.id=?').bind(SINGLE_USER_ID).first<{timezone:string;daily_minutes:number}>();if(!profile)return c.json({error:'Bootstrap required'},409);return c.json(await getToday(c.env.DB,profile.timezone,profile.daily_minutes));});
api.get('/today/session',async(c)=>{const profile=await c.env.DB.prepare('SELECT timezone,daily_minutes FROM users u JOIN learner_profiles p ON p.user_id=u.id WHERE u.id=?').bind(SINGLE_USER_ID).first<{timezone:string;daily_minutes:number}>();if(!profile)return c.json({needsBootstrap:true},409);const today=await getToday(c.env.DB,profile.timezone,profile.daily_minutes);const current=today.items.find((item)=>(item as {status:string}).status!=='complete')??null;return c.json({...today,current});});
api.post('/today/items/:id/start',async(c)=>{const item=await startDailyItem(c.env.DB,c.req.param('id'));return item?c.json({ok:true,item}):c.json({error:'Daily plan item not found.'},404);});
api.post('/today/items/:id/complete',async(c)=>{const result=await c.req.json().catch(()=>({}));const completed=await completeDailyItem(c.env.DB,c.req.param('id'),result);return completed?c.json({ok:true,...completed}):c.json({error:'Daily plan item not found.'},404);});
api.post('/missions/:id',async(c)=>{const input=await c.req.json() as {status?:unknown;actualUsage?:unknown;reflection?:unknown;naturalness?:unknown};const status=input.status==='used'?'used':'not_used';const naturalness=typeof input.naturalness==='number'?Math.max(1,Math.min(5,Math.round(input.naturalness))):null;const actualUsage=typeof input.actualUsage==='string'?input.actualUsage.slice(0,2000):'';const mission=await c.env.DB.prepare(`SELECT target_units_json FROM missions WHERE id=? AND user_id=?`).bind(c.req.param('id'),SINGLE_USER_ID).first<{target_units_json:string}>();if(!mission)return c.json({error:'Mission not found.'},404);await c.env.DB.prepare(`UPDATE missions SET status=?,actual_usage=?,reflection=?,naturalness=?,completed_at=CURRENT_TIMESTAMP WHERE id=?`).bind(status,actualUsage||null,typeof input.reflection==='string'?input.reflection.slice(0,2000):null,naturalness,c.req.param('id')).run();if(status==='used'){for(const unitId of json<string[]>(mission.target_units_json,[])){const unit=await c.env.DB.prepare('SELECT term FROM learning_units WHERE id=?').bind(unitId).first<{term:string}>();await recordLearningEvidence(c.env.DB,{unitId,source:'mission',dimension:'transfer',score:(naturalness??3)*20,verified:Boolean(unit&&responseContainsUnit(actualUsage,unit.term)),responseText:actualUsage,metadata:{missionId:c.req.param('id')}});}}return c.json({ok:true,status});});

api.get('/drills/queue',async(c)=>{const limit=Math.min(20,Math.max(1,Number(c.req.query('limit')??10)));const today=localDate(c.env.APP_TIMEZONE||'America/New_York');const rows=await c.env.DB.prepare(`SELECT u.id,u.term,u.definition_en,u.definition_zh,u.examples_json,
  s.recall_score,s.production_score,s.transfer_score,
  (CASE WHEN p.target_units_json LIKE '%'||u.id||'%' THEN 1 ELSE 0 END) today_target,
  (0.40*MAX(0,(s.recall_score-s.production_score)/100.0)
    +0.25*(CASE WHEN p.target_units_json LIKE '%'||u.id||'%' THEN 1 ELSE 0 END)
    +0.15*(1-s.transfer_score/100.0)
    +0.10*COALESCE(s.priority_override,u.priority)
    +0.10*CASE WHEN s.last_lapse_at>=datetime('now','-14 days') THEN 1 ELSE 0 END) adaptive_score
  FROM learning_units u JOIN user_unit_states s ON s.unit_id=u.id AND s.user_id=?
  LEFT JOIN daily_plans p ON p.user_id=s.user_id AND p.local_date=?
  WHERE u.active=1 AND s.suspended=0 AND s.status<>'unseen'
  ORDER BY adaptive_score DESC,s.last_seen_at DESC LIMIT ?`).bind(SINGLE_USER_ID,today,limit).all<Record<string,unknown>>();return c.json({units:rows.results.map((row)=>{const examples=json<Array<string|{text:string}>>(String(row.examples_json),[]);const first=examples[0];return{...row,model_answer:typeof first==='string'?first:first?.text??String(row.term)};})});});
api.post('/drills/sessions',async(c)=>{const body=await c.req.json().catch(()=>({})) as {planItemId?:unknown};const planItemId=typeof body.planItemId==='string'?body.planItemId.slice(0,160):null;if(planItemId&&!await startDailyItem(c.env.DB,planItemId))return c.json({error:'Daily plan item not found.'},404);const id=crypto.randomUUID();await c.env.DB.prepare(`INSERT INTO practice_sessions(id,user_id,session_type,mode,plan_item_id,title) VALUES(?,'primary','automaticity','drill',?,'Automaticity sprint')`).bind(id,planItemId).run();return c.json({id},201);});
api.post('/drills/sessions/:id/answers',async(c)=>{const contentType=c.req.header('content-type')??'';let raw:unknown;let audioKey:string|undefined;if(contentType.includes('multipart/form-data')){const form=await c.req.formData();const audio=form.get('audio');if(!(audio instanceof File))return c.json({error:'Audio file is required.'},400);if(audio.size>AUDIO_MAX_BYTES||!AUDIO_MIME_TYPES.includes(audio.type as typeof AUDIO_MIME_TYPES[number]))return c.json({error:'Unsupported or oversized audio. Maximum 12 MB.'},413);audioKey=`audio/drills/${c.req.param('id')}/${crypto.randomUUID()}`;await c.env.AUDIO_BUCKET.put(audioKey,audio.stream(),{httpMetadata:{contentType:audio.type},customMetadata:{retentionDays:c.env.AUDIO_RETENTION_DAYS}});const transcript=await createProviders(c.env).stt.transcribe(await audio.arrayBuffer(),audio.type);raw={unitId:String(form.get('unitId')??''),prompt:String(form.get('prompt')??''),response:transcript.text,responseMs:Number(form.get('responseMs')??0),variant:Number(form.get('variant')??0),planItemId:String(form.get('planItemId')??'')||undefined};}else raw=await c.req.json();const input=parse(drillAnswerSchema,raw);const unit=await c.env.DB.prepare('SELECT term FROM learning_units WHERE id=? AND active=1').bind(input.unitId).first<{term:string}>();if(!unit)return c.json({error:'Learning unit not found.'},404);const usesTarget=responseContainsUnit(input.response,unit.term);const hasSentence=input.variant===1||input.response.trim().split(/\s+/).length>=3;const correct=usesTarget&&hasSentence;const score=correct?(input.responseMs<=8_000?90:76):usesTarget?55:20;const count=await c.env.DB.prepare('SELECT COUNT(*) count FROM practice_turns WHERE session_id=?').bind(c.req.param('id')).first<{count:number}>();const turnIndex=count?.count??0;await c.env.DB.batch([c.env.DB.prepare(`INSERT INTO practice_turns(id,session_id,turn_index,speaker,text,audio_object_key,duration_ms) VALUES(?,?,?,?,?,?,?)`).bind(crypto.randomUUID(),c.req.param('id'),turnIndex,'user',input.response,audioKey??null,input.responseMs),c.env.DB.prepare(`UPDATE practice_sessions SET duration_seconds=duration_seconds+?,objective_metrics_json=? WHERE id=?`).bind(Math.round(input.responseMs/1000),JSON.stringify({lastUnitId:input.unitId,lastVariant:input.variant,lastCorrect:correct,lastScore:score}),c.req.param('id'))]);const evidence=await recordLearningEvidence(c.env.DB,{unitId:input.unitId,source:'drill',dimension:'production',score,verified:true,responseText:input.response,responseMs:input.responseMs,sessionId:c.req.param('id'),metadata:{variant:input.variant,audio:Boolean(audioKey)}});return c.json({ok:true,correct,score,transcript:input.response,status:evidence.status,mastery:evidence.scores,feedback:correct?'Target expression verified in a complete response.':usesTarget?'Use the target in a complete natural sentence.':`Include “${unit.term}” in your response.`});});
api.post('/drills/sessions/:id/complete',async(c)=>{const session=await c.env.DB.prepare(`SELECT plan_item_id FROM practice_sessions WHERE id=? AND mode='drill'`).bind(c.req.param('id')).first<{plan_item_id:string|null}>();if(!session)return c.json({error:'Drill session not found.'},404);await c.env.DB.prepare(`UPDATE practice_sessions SET status='complete',completed_at=CURRENT_TIMESTAMP WHERE id=?`).bind(c.req.param('id')).run();if(session.plan_item_id)await completeDailyItem(c.env.DB,session.plan_item_id,{sessionId:c.req.param('id')});return c.json({ok:true});});

api.get('/units',async(c)=>{const query=c.req.query('q')?.trim();const domain=c.req.query('domain');const status=c.req.query('status');const clauses=['u.active=1'];const values:unknown[]=[];if(query){clauses.push('(u.term LIKE ? OR u.definition_en LIKE ?)');values.push(`%${query}%`,`%${query}%`);}if(domain){clauses.push('u.domains_json LIKE ?');values.push(`%${domain}%`);}if(status){clauses.push('s.status=?');values.push(status);}const rows=await c.env.DB.prepare(`SELECT u.id,u.term,u.unit_type,u.cefr,u.register,u.domains_json,u.definition_en,u.definition_zh,u.priority,s.status,s.recognition_score,s.recall_score,s.production_score,s.transfer_score FROM learning_units u JOIN user_unit_states s ON s.unit_id=u.id AND s.user_id='primary' WHERE ${clauses.join(' AND ')} ORDER BY u.priority DESC,u.term LIMIT 200`).bind(...values).all();return c.json({units:rows.results});});
api.get('/units/:id',async(c)=>{const unit=await c.env.DB.prepare(`SELECT u.*,s.status,s.recognition_score,s.recall_score,s.production_score,s.transfer_score FROM learning_units u LEFT JOIN user_unit_states s ON s.unit_id=u.id AND s.user_id='primary' WHERE u.id=?`).bind(c.req.param('id')).first();if(!unit)return c.json({error:'Unit not found'},404);const examples=await c.env.DB.prepare('SELECT * FROM personal_examples WHERE unit_id=? ORDER BY created_at DESC').bind(c.req.param('id')).all();return c.json({unit,personalExamples:examples.results});});
api.post('/units/:id/complete',async(c)=>{const input=parse(unitCompleteSchema,await c.req.json().catch(()=>({})));const unit=await c.env.DB.prepare('SELECT id FROM learning_units WHERE id=? AND active=1').bind(c.req.param('id')).first<{id:string}>();if(!unit)return c.json({error:'Unit not found.'},404);const evidence=await recordLearningEvidence(c.env.DB,{unitId:unit.id,source:'learn',dimension:'recognition',score:65,verified:true,metadata:{targetIndex:input.targetIndex??null}});return c.json({ok:true,evidence,planItemId:input.planItemId??null});});
api.post('/units/:id/personal-example',async(c)=>{const input=parse(personalExampleSchema,await c.req.json());const id=crypto.randomUUID();await c.env.DB.prepare(`INSERT INTO personal_examples(id,user_id,unit_id,text) VALUES(?,'primary',?,?)`).bind(id,c.req.param('id'),input.text).run();await recordLearningEvidence(c.env.DB,{unitId:c.req.param('id'),source:'personal_example',dimension:'production',score:65,verified:false,responseText:input.text});return c.json({id},201);});

api.get('/reviews/due',async(c)=>{const limit=Math.min(100,Math.max(1,Number(c.req.query('limit')??20)));const rows=await c.env.DB.prepare(`SELECT c.*,u.term,u.definition_en,u.definition_zh,u.collocations_json,u.examples_json FROM review_cards c JOIN learning_units u ON u.id=c.unit_id WHERE c.user_id='primary' AND c.active=1 AND c.due_at<=? ORDER BY c.due_at,u.priority DESC LIMIT ?`).bind(nowIso(),limit).all();return c.json({cards:rows.results});});
api.post('/reviews/:cardId/answer',async(c)=>{const input=parse(reviewAnswerSchema,await c.req.json());const row=await c.env.DB.prepare(`SELECT c.* FROM review_cards c WHERE c.id=? AND c.user_id=? AND c.active=1`).bind(c.req.param('cardId'),SINGLE_USER_ID).first<Record<string,unknown>>();if(!row)return c.json({error:'Review card not found'},404);const suggested=suggestRating(input.correct,input.responseMs,input.hintLevel);const grade=(input.rating??suggested) as Grade;const parsed=json<Record<string,unknown>>(String(row.fsrs_json),{});const card:CardInput={due:String(row.due_at),stability:Number(row.stability),difficulty:Number(row.difficulty),elapsed_days:Number(row.elapsed_days),scheduled_days:Number(row.scheduled_days),learning_steps:Number(row.learning_steps),reps:Number(row.reps),lapses:Number(row.lapses),state:Number(row.state),last_review:row.last_review_at?String(row.last_review_at):null};const reviewedAt=new Date();const next=scheduleReview(card,grade,reviewedAt);const dimension=row.card_type==='recognition'?'recognition':'recall';const eventId=crypto.randomUUID();await c.env.DB.batch([c.env.DB.prepare(`UPDATE review_cards SET state=?,due_at=?,stability=?,difficulty=?,elapsed_days=?,scheduled_days=?,learning_steps=?,reps=?,lapses=?,last_review_at=?,fsrs_json=?,updated_at=CURRENT_TIMESTAMP WHERE id=?`).bind(next.card.state,next.card.due.toISOString(),next.card.stability,next.card.difficulty,next.card.elapsed_days,next.card.scheduled_days,next.card.learning_steps,next.card.reps,next.card.lapses,next.card.last_review?.toISOString()??null,JSON.stringify(next.card),c.req.param('cardId')),c.env.DB.prepare(`INSERT INTO review_events(id,card_id,unit_id,reviewed_at,rating,suggested_rating,correct,response_text,response_ms,hint_level,previous_state_json,next_state_json) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)`).bind(eventId,c.req.param('cardId'),row.unit_id,reviewedAt.toISOString(),grade,suggested,input.correct?1:0,input.response,input.responseMs,input.hintLevel,JSON.stringify(parsed),JSON.stringify(next.card)),c.env.DB.prepare(`UPDATE user_unit_states SET correct_reviews=correct_reviews+? WHERE user_id=? AND unit_id=?`).bind(input.correct?1:0,SINGLE_USER_ID,row.unit_id)]);const numericGrade=Number(grade);const score=input.correct?(numericGrade===4?95:numericGrade===3?82:68):20;const evidence=await recordLearningEvidence(c.env.DB,{unitId:String(row.unit_id),source:'review',dimension,score,verified:true,responseText:input.response,responseMs:input.responseMs,metadata:{cardId:c.req.param('cardId'),cardType:row.card_type,rating:grade}});return c.json({eventId,suggestedRating:suggested,rating:grade,nextDue:next.card.due,status:evidence.status,mastery:evidence.scores});});
api.post('/reviews/:cardId/override-rating',async(c)=>{const input=parse(reviewAnswerSchema.pick({rating:true}).required(),await c.req.json());const latest=await c.env.DB.prepare(`SELECT e.id,e.reviewed_at,e.previous_state_json,c.* FROM review_events e JOIN review_cards c ON c.id=e.card_id WHERE e.card_id=? ORDER BY e.reviewed_at DESC LIMIT 1`).bind(c.req.param('cardId')).first<Record<string,unknown>>();if(!latest)return c.json({error:'No review to override'},404);const previous=json<CardInput>(String(latest.previous_state_json),{} as CardInput);const next=scheduleReview(previous,input.rating as Grade,new Date(String(latest.reviewed_at)));await c.env.DB.batch([c.env.DB.prepare('UPDATE review_events SET rating=?,next_state_json=? WHERE id=?').bind(input.rating,JSON.stringify(next.card),latest.id),c.env.DB.prepare(`UPDATE review_cards SET state=?,due_at=?,stability=?,difficulty=?,elapsed_days=?,scheduled_days=?,learning_steps=?,reps=?,lapses=?,last_review_at=?,fsrs_json=?,updated_at=CURRENT_TIMESTAMP WHERE id=?`).bind(next.card.state,next.card.due.toISOString(),next.card.stability,next.card.difficulty,next.card.elapsed_days,next.card.scheduled_days,next.card.learning_steps,next.card.reps,next.card.lapses,next.card.last_review?.toISOString()??null,JSON.stringify(next.card),c.req.param('cardId'))]);return c.json({ok:true,nextDue:next.card.due,note:'Rating override applied and the FSRS schedule was recalculated.'});});

