api.post('/speaking/sessions/:id/turns',async(c)=>{const sessionId=c.req.param('id');const contentType=c.req.header('content-type')??'';let text='';let durationMs:number|undefined;let audioKey:string|undefined;if(contentType.includes('multipart/form-data')){const form=await c.req.formData();const audio=form.get('audio');if(!(audio instanceof File))return c.json({error:'Audio file is required'},400);if(audio.size>AUDIO_MAX_BYTES||!AUDIO_MIME_TYPES.includes(audio.type as typeof AUDIO_MIME_TYPES[number]))return c.json({error:'Unsupported or oversized audio. Maximum 12 MB.'},413);audioKey=`audio/${sessionId}/${crypto.randomUUID()}`;await c.env.AUDIO_BUCKET.put(audioKey,audio.stream(),{httpMetadata:{contentType:audio.type},customMetadata:{retentionDays:c.env.AUDIO_RETENTION_DAYS}});text=(await createProviders(c.env).stt.transcribe(await audio.arrayBuffer(),audio.type)).text;durationMs=Number(form.get('durationMs')??0)||undefined;}else{const input=parse(speakingTurnSchema,await c.req.json());text=input.text;durationMs=input.durationMs;}
  const context=await loadSpeakingContext(c.env.DB,sessionId);if(!context)return c.json({error:'Session not found.'},404);const count=await c.env.DB.prepare('SELECT COUNT(*) count FROM practice_turns WHERE session_id=?').bind(sessionId).first<{count:number}>();const index=count?.count??0;const userTurns=Math.ceil(index/2);if(context.scenario&&userTurns>=context.scenario.maxTurns)return c.json({error:'Scenario turn limit reached. Finish and analyze the session.'},409);await c.env.DB.prepare(`INSERT INTO practice_turns(id,session_id,turn_index,speaker,text,audio_object_key,duration_ms) VALUES(?,?,?,?,?,?,?)`).bind(crypto.randomUUID(),sessionId,index,'user',text,audioKey??null,durationMs??null).run();const contextRows=await c.env.DB.prepare('SELECT speaker,text FROM practice_turns WHERE session_id=? ORDER BY turn_index DESC LIMIT 12').bind(sessionId).all<{speaker:string;text:string}>();const ai=await createProviders(c.env).text.generateText({taskType:'roleplay',system:`${roleplayPrompt}\n\n${speakingInstructions(context)}`,prompt:contextRows.results.reverse().map((t)=>`${t.speaker}: ${t.text}`).join('\n'),modelRole:'daily_fast',sensitive:true});const aiIndex=index+1;await c.env.DB.prepare(`INSERT INTO practice_turns(id,session_id,turn_index,speaker,text) VALUES(?,?,?,?,?)`).bind(crypto.randomUUID(),sessionId,aiIndex,'assistant',ai.text).run();return c.json({user:{text,audioKey},assistant:{text:ai.text},turnIndex:aiIndex,scenario:context.scenario});});

const requireOwner=(c:{req:{header:(name:string)=>string|undefined;url:string};env:Env})=>authorizeOwner(c.req,c.env);
const realtimeEnabled=(env:Env)=>env.REALTIME_SPEAK_ENABLED==='true' || env.REALTIME_SPEAK_ENABLED==='1';
const realtimeSession=async(c:{env:Env},sessionId:string)=>c.env.DB.prepare('SELECT id,user_id,mode,status,duration_seconds FROM practice_sessions WHERE id=? AND user_id=?').bind(sessionId,SINGLE_USER_ID).first<{id:string;user_id:string;mode:string;status:string;duration_seconds:number}>();

api.post('/realtime/client-secret',async(c)=>{
  if(!realtimeEnabled(c.env))return c.json({error:'Realtime Speak is disabled.'},404);
  const owner=requireOwner(c);if(!owner.ok)return c.json({error:owner.error},owner.status);
  let input;try{input=parse(realtimeClientSecretSchema,await c.req.json());}catch{return c.json({error:'Invalid realtime request.'},400);}
  const session=await realtimeSession(c,input.sessionId);if(!session)return c.json({error:'Session not found.'},404);
  if(session.status!=='active'||session.mode!==input.mode)return c.json({error:'Session is not available for realtime.'},409);
  if((Number(session.duration_seconds)||0)+input.durationSeconds>900)return c.json({error:'Session duration limit reached.'},429);
  if(!await checkRate(c.env.DB,`realtime:${owner.email.toLowerCase()}`,10,1))return c.json({error:'Realtime rate limit exceeded.'},429);
  const endpoint=c.env.AZURE_OPENAI_ENDPOINT;const deployment=c.env.AZURE_REALTIME_DEPLOYMENT;
  const context=await loadSpeakingContext(c.env.DB,input.sessionId);if(!context)return c.json({error:'Session not found.'},404);
  const instructions=`You are Eric's English speaking coach. Keep responses concise and natural.\n${speakingInstructions(context)}`;
  try{
    const token=await mintAzureRealtimeClientSecret({endpoint,deployment,apiKey:c.env.AZURE_OPENAI_API_KEY,timeoutMs:8_000},{mode:input.mode,durationSeconds:input.durationSeconds,instructions});
    const signalingUrl=endpoint?azureRealtimeClientSecretUrl(endpoint).replace('/client_secrets','/calls'):null;
    return c.json({clientSecret:token.value,expiresAt:token.expiresAt,signalingUrl,deployment,sessionId:input.sessionId,maxDurationSeconds:input.durationSeconds});
  }catch(error){
    const code=error instanceof AzureRealtimeError?error.code:'provider_error';
    const status=code==='rate_limited'?429:code==='unauthorized'||code==='forbidden'?502:code==='configuration'?503:502;
    return c.json({error:code==='configuration'?'Realtime is not configured.':'Realtime provider unavailable.',code,requestId:c.get('requestId')},status as 429|502|503);
  }
});

api.post('/realtime/sessions/:id/events',async(c)=>{
  if(!realtimeEnabled(c.env))return c.json({error:'Realtime Speak is disabled.'},404);
  const owner=requireOwner(c);if(!owner.ok)return c.json({error:owner.error},owner.status);
  let input;try{input=parse(realtimeEventSchema,await c.req.json());}catch{return c.json({error:'Invalid realtime event.'},400);}
  const sessionId=c.req.param('id');
  const session=await realtimeSession(c,sessionId);
  if(!session||session.id!==sessionId)return c.json({error:'Session not found.'},404);
  const inserted=await c.env.DB.prepare('INSERT OR IGNORE INTO realtime_events(event_id,session_id,event_type,text,duration_ms,payload_json) VALUES(?,?,?,?,?,?)').bind(input.eventId,sessionId,input.eventType,input.text??null,input.durationMs??null,JSON.stringify(input.payload??{})).run();
  if(!inserted.meta.changes)return c.json({ok:true,deduplicated:true});
  if((input.eventType==='user_transcript'||input.eventType==='assistant_transcript')&&input.text?.trim()){
    const count=await c.env.DB.prepare('SELECT COUNT(*) count FROM practice_turns WHERE session_id=?').bind(sessionId).first<{count:number}>();
    try{await c.env.DB.prepare('INSERT INTO practice_turns(id,session_id,turn_index,speaker,text,duration_ms) VALUES(?,?,?,?,?,?)').bind(crypto.randomUUID(),sessionId,count?.count??0,input.eventType==='user_transcript'?'user':'assistant',input.text??'',input.durationMs??null).run();}catch{/* another event may have claimed this turn index; the event itself remains durable */}
  }
  if(input.eventType==='session_finished'&&input.durationMs!==undefined)await c.env.DB.prepare('UPDATE practice_sessions SET duration_seconds=MIN(900, duration_seconds+?) WHERE id=?').bind(Math.round(input.durationMs/1000),sessionId).run();
  return c.json({ok:true,deduplicated:false});
});
api.post('/speaking/sessions/:id/finish',async(c)=>{const sessionId=c.req.param('id');const context=await loadSpeakingContext(c.env.DB,sessionId);if(!context)return c.json({error:'Session not found.'},404);await c.env.DB.prepare(`UPDATE practice_sessions SET status='processing' WHERE id=?`).bind(sessionId).run();try{await c.env.SESSION_ANALYSIS.create({id:`session-${sessionId}`,params:{sessionId}});return c.json({status:'processing'},202);}catch{const turns=await c.env.DB.prepare('SELECT speaker,text,duration_ms FROM practice_turns WHERE session_id=? ORDER BY turn_index').bind(sessionId).all<{speaker:string;text:string;duration_ms:number|null}>();const targets=context.scenario?.targetUnits??[];const evaluation=await evaluateSpeaking(c.env,turns.results.map((t)=>`${t.speaker}: ${t.text}`).join('\n'),targets);const speakingMs=turns.results.filter((turn)=>turn.speaker==='user').reduce((total,turn)=>total+Number(turn.duration_ms??0),0);await c.env.DB.prepare(`UPDATE practice_sessions SET status='complete',completed_at=CURRENT_TIMESTAMP,duration_seconds=?,evaluation_json=? WHERE id=?`).bind(Math.round(speakingMs/1000),JSON.stringify(evaluation),sessionId).run();await persistCorrections(c.env.DB,'speaking',sessionId,evaluation.priorityCorrections);await recordSpeakingEvaluationEvidence(c.env.DB,sessionId,targets,evaluation);if(context.planItemId)await completeDailyItem(c.env.DB,context.planItemId,{sessionId});return c.json({status:'complete',evaluation});}});
