api.post('/speaking/sessions/:id/retry-attempt',async(c)=>{const form=await c.req.formData();const audio=form.get('audio');if(!(audio instanceof File))return c.json({error:'Audio file is required.'},400);if(audio.size>AUDIO_MAX_BYTES||!AUDIO_MIME_TYPES.includes(audio.type as typeof AUDIO_MIME_TYPES[number]))return c.json({error:'Unsupported or oversized audio. Maximum 12 MB.'},413);const correctionIndex=Math.max(0,Math.min(20,Number(form.get('correctionIndex')??0)));const responseMs=Math.max(0,Math.min(300_000,Number(form.get('responseMs')??0)));const session=await c.env.DB.prepare('SELECT evaluation_json FROM practice_sessions WHERE id=? AND user_id=?').bind(c.req.param('id'),SINGLE_USER_ID).first<{evaluation_json:string}>();if(!session)return c.json({error:'Session not found.'},404);const evaluation=json<{priorityCorrections:Array<{improved:string}>}>(session.evaluation_json,{priorityCorrections:[]});const model=evaluation.priorityCorrections[correctionIndex]?.improved;if(!model)return c.json({error:'Correction not found.'},404);const audioKey=`audio/retries/${c.req.param('id')}/${crypto.randomUUID()}`;await c.env.AUDIO_BUCKET.put(audioKey,audio.stream(),{httpMetadata:{contentType:audio.type},customMetadata:{retentionDays:c.env.AUDIO_RETENTION_DAYS}});const transcript=(await createProviders(c.env).stt.transcribe(await audio.arrayBuffer(),audio.type)).text;const expectedWords=new Set(normalizedText(model).split(' ').filter(Boolean));const actualWords=new Set(normalizedText(transcript).split(' ').filter(Boolean));const overlap=[...expectedWords].filter((word)=>actualWords.has(word)).length/Math.max(expectedWords.size,1);const score=Math.round(overlap*100);const passed=score>=75;const feedback=passed?'Re-say verified. Now reuse the pattern in a new sentence.':'Try again with the missing content words and the same word order.';await c.env.DB.prepare(`INSERT INTO retry_attempts(id,session_id,correction_index,transcript,audio_object_key,score,passed,feedback,response_ms) VALUES(?,?,?,?,?,?,?,?,?)`).bind(crypto.randomUUID(),c.req.param('id'),correctionIndex,transcript,audioKey,score,passed?1:0,feedback,responseMs).run();await recordTextEvidenceForMatches(c.env.DB,{source:'resay',dimension:'production',text:transcript,score:passed?85:35,verified:true,sessionId:c.req.param('id')});return c.json({transcript,score,passed,feedback,audioKey});});
api.get('/audio/manifest',async(c)=>{let cursor:string|undefined;const objects:Array<{key:string;size:number;uploaded:string;downloadUrl:string}>=[];do{const listed=await c.env.AUDIO_BUCKET.list({prefix:'audio/',cursor,limit:1000});objects.push(...listed.objects.map((object)=>({key:object.key,size:object.size,uploaded:object.uploaded.toISOString(),downloadUrl:`/api/audio/${encodeURIComponent(object.key)}`})));cursor=listed.truncated?listed.cursor:undefined;}while(cursor);return c.json({objects});});
api.post('/audio/tts',async(c)=>{
  const owner=requireOwner(c);if(!owner.ok)return c.json({error:owner.error},owner.status);
  const parsed=ttsRequestSchema.safeParse(await c.req.json().catch(()=>null));
  if(!parsed.success)return c.json({error:'Invalid TTS request.',issues:parsed.error.issues.map((issue)=>({path:issue.path,message:issue.message}))},400);
  try {
    const result=await synthesizeAndCache(c.env,parsed.data);
    return c.json({...result,audioUrl:`/api/audio/${encodeURIComponent(result.key)}`,fallback:false});
  } catch(error) {
    const message=error instanceof Error?error.message:'TTS unavailable';
    return c.json({error:message,fallback:true},/limit|not configured/i.test(message)?503:502);
  }
});
api.get('/audio/:key{.+}',async(c)=>{const key=decodeURIComponent(c.req.param('key'));if(!key.startsWith('audio/'))return c.json({error:'Invalid audio key'},400);if(key.startsWith('audio/tts/')){const owner=requireOwner(c);if(!owner.ok)return c.json({error:owner.error},owner.status);}const object=await c.env.AUDIO_BUCKET.get(key);if(!object)return c.json({error:'Audio not found'},404);const headers=new Headers();object.writeHttpMetadata(headers);headers.set('etag',object.httpEtag);headers.set('cache-control',key.startsWith('audio/tts/')?'private, max-age=31536000, immutable':'private, no-store');if(!key.startsWith('audio/tts/'))headers.set('content-disposition',`attachment; filename="${key.split('/').at(-1)??'recording'}"`);return new Response(object.body,{headers});});

