api.post('/event-prep',async(c)=>{const input=parse(eventPrepSchema,await c.req.json());const redacted=redactPii(input.event).redacted;const candidates=await c.env.DB.prepare(`SELECT u.id,u.term,u.definition_en,u.domains_json,s.status,s.production_score,s.transfer_score FROM learning_units u JOIN user_unit_states s ON s.unit_id=u.id AND s.user_id=? WHERE u.active=1 ORDER BY CASE WHEN s.status<>'unseen' THEN 0 ELSE 1 END,COALESCE(s.priority_override,u.priority) DESC LIMIT 60`).bind(SINGLE_USER_ID).all<Record<string,unknown>>();const recurring=await c.env.DB.prepare(`SELECT category,description FROM error_patterns WHERE user_id=? AND last_seen_at>=datetime('now','-30 days') ORDER BY impact_score DESC LIMIT 3`).bind(SINGLE_USER_ID).all();const generated=await createProviders(c.env).text.generateStructured({taskType:'event_prep',system:eventPrepPrompt,prompt:JSON.stringify({event:redacted,candidateExpressions:candidates.results,recurringErrors:recurring.results}),modelRole:'daily_fast',sensitive:true},eventPrepResultSchema);const candidateByTerm=new Map(candidates.results.map((row)=>[normalizedText(String(row.term)),{id:String(row.id),term:String(row.term)}]));const mustUse=generated.mustUseTerms.map((term)=>candidateByTerm.get(normalizedText(term))).filter((unit):unit is {id:string;term:string}=>Boolean(unit));if(mustUse.length<3){for(const row of candidates.results){const unit={id:String(row.id),term:String(row.term)};if(!mustUse.some((item)=>item.id===unit.id))mustUse.push(unit);if(mustUse.length===5)break;}}const prep={mustUse:mustUse.slice(0,5),recommendedOpening:generated.recommendedOpening,likelyFollowUps:generated.likelyFollowUps,possibleResponses:generated.possibleResponses,cheatSheet:generated.cheatSheet,followUpMessage:generated.followUpMessage};const id=crypto.randomUUID();await c.env.DB.prepare(`INSERT INTO event_preps(id,user_id,event_text,prep_json) VALUES(?,'primary',?,?)`).bind(id,input.event,JSON.stringify(prep)).run();return c.json({id,event:input.event,...prep},201);});
api.get('/event-prep/:id',async(c)=>{const row=await c.env.DB.prepare('SELECT * FROM event_preps WHERE id=?').bind(c.req.param('id')).first();return row?c.json(row):c.json({error:'Preparation not found'},404);});
api.post('/event-prep/:id/after-action',async(c)=>{const input=parse(afterActionSchema,await c.req.json());const prepRow=await c.env.DB.prepare('SELECT prep_json FROM event_preps WHERE id=? AND user_id=?').bind(c.req.param('id'),SINGLE_USER_ID).first<{prep_json:string}>();if(!prepRow)return c.json({error:'Preparation not found.'},404);const captureText=[input.happened,input.missedPhrase,input.unfamiliarExpression].filter(Boolean).join('\n');const redaction=redactPii(captureText);const extracted=await extractCapture(c.env,redaction.redacted,'After-action review');const unitIds=await persistCandidateUnits(c.env.DB,extracted.units,'after_action');const evidenceUnitIds=await recordTextEvidenceForMatches(c.env.DB,{source:'after_action',dimension:'transfer',text:redaction.redacted,score:82,verified:true});await persistCorrections(c.env.DB,'after_action',c.req.param('id'),extracted.errors);const prep=json<{followUpMessage?:string}>(prepRow.prep_json,{});const after={...input,redaction,extracted,unitIds,evidenceUnitIds,followUp:input.createFollowUp?prep.followUpMessage??'Thanks for speaking with me. I’m following up to confirm the details and next step we discussed.':null};await c.env.DB.prepare(`UPDATE event_preps SET after_action_json=?,status='complete',completed_at=CURRENT_TIMESTAMP WHERE id=?`).bind(JSON.stringify(after),c.req.param('id')).run();return c.json(after);});

api.post('/captures',async(c)=>{const input=parse(captureSchema,await c.req.json());const redaction=redactPii(input.text,input.redactAddresses);const extracted=await extractCapture(c.env,redaction.redacted,input.context);const id=crypto.randomUUID();const unitIds=await persistCandidateUnits(c.env.DB,extracted.units,'capture');const evidenceUnitIds=await recordTextEvidenceForMatches(c.env.DB,{source:'capture',dimension:'transfer',text:redaction.redacted,score:78,verified:true});await c.env.DB.prepare(`INSERT INTO real_world_captures(id,user_id,capture_type,raw_text,redacted_text,context,extracted_json) VALUES(?,'primary',?,?,?,?,?)`).bind(id,input.captureType,input.text,redaction.redacted,input.context,JSON.stringify({...extracted,unitIds,evidenceUnitIds})).run();await persistCorrections(c.env.DB,'capture',id,extracted.errors);return c.json({id,redactionPreview:redaction,extracted,unitIds,evidenceUnitIds},201);});
api.post('/captures/audio',async(c)=>{const form=await c.req.formData();const audio=form.get('audio');if(!(audio instanceof File))return c.json({error:'Audio file is required.'},400);if(audio.size>AUDIO_MAX_BYTES||!AUDIO_MIME_TYPES.includes(audio.type as typeof AUDIO_MIME_TYPES[number]))return c.json({error:'Unsupported or oversized audio. Maximum 12 MB.'},413);const context=String(form.get('context')??'').slice(0,2000);const audioKey=`audio/captures/${crypto.randomUUID()}`;await c.env.AUDIO_BUCKET.put(audioKey,audio.stream(),{httpMetadata:{contentType:audio.type},customMetadata:{retentionDays:c.env.AUDIO_RETENTION_DAYS}});const transcript=await createProviders(c.env).stt.transcribe(await audio.arrayBuffer(),audio.type);const redaction=redactPii(transcript.text);const extracted=await extractCapture(c.env,redaction.redacted,context);const id=crypto.randomUUID();const unitIds=await persistCandidateUnits(c.env.DB,extracted.units,'capture_audio');const evidenceUnitIds=await recordTextEvidenceForMatches(c.env.DB,{source:'capture_audio',dimension:'transfer',text:redaction.redacted,score:84,verified:true});await c.env.DB.prepare(`INSERT INTO real_world_captures(id,user_id,capture_type,raw_text,redacted_text,context,audio_object_key,extracted_json) VALUES(?,'primary','call_review',?,?,?,?,?)`).bind(id,transcript.text,redaction.redacted,context,audioKey,JSON.stringify({...extracted,unitIds,evidenceUnitIds})).run();await persistCorrections(c.env.DB,'capture',id,extracted.errors);return c.json({id,transcript:transcript.text,redactionPreview:redaction,extracted,unitIds,evidenceUnitIds},201);});
api.get('/captures',async(c)=>{const rows=await c.env.DB.prepare('SELECT id,capture_type,redacted_text,context,extracted_json,created_at FROM real_world_captures ORDER BY created_at DESC LIMIT 100').all();return c.json({captures:rows.results});});

api.get('/patterns',async(c)=>{const rows=await c.env.DB.prepare(`SELECT e.*,
  (SELECT COUNT(*) FROM feedback_items f WHERE f.user_id=e.user_id AND f.category=e.category AND f.last_seen_at>=datetime('now','-30 days')) count_30d,
  CASE WHEN (SELECT COUNT(*) FROM feedback_items f WHERE f.user_id=e.user_id AND f.category=e.category AND f.last_seen_at>=datetime('now','-30 days'))>=3 THEN json_object('title','Focused retry: '||e.category,'minutes',7,'steps',json_array('Notice the pattern','Rebuild three examples','Use it in a timed response')) ELSE NULL END micro_lesson
  FROM error_patterns e WHERE e.user_id='primary' ORDER BY count_30d DESC,e.impact_score DESC`).all();return c.json({patterns:rows.results});});
api.get('/progress/summary',async(c)=>{const states=await c.env.DB.prepare(`SELECT status,COUNT(*) count FROM user_unit_states WHERE user_id='primary' GROUP BY status`).all();const reviews=await c.env.DB.prepare(`SELECT COUNT(*) reviews,ROUND(AVG(e.correct)*100,1) activeRecallAccuracy FROM review_events e JOIN review_cards c ON c.id=e.card_id WHERE c.card_type='active_recall' AND e.reviewed_at>=datetime('now','-30 days')`).first();const speaking=await c.env.DB.prepare(`SELECT ROUND(COALESCE(SUM(duration_seconds),0)/60.0,1) speakingMinutes FROM practice_sessions WHERE session_type='speaking' AND started_at>=datetime('now','-30 days')`).first();const transfer=await c.env.DB.prepare(`SELECT COUNT(DISTINCT unit_id) transferCount FROM learning_evidence WHERE dimension='transfer' AND score>=65 AND created_at>=datetime('now','-30 days')`).first();const errors=await c.env.DB.prepare(`SELECT COUNT(*) recurrentErrors FROM feedback_items WHERE last_seen_at>=datetime('now','-30 days')`).first();const profile=await c.env.DB.prepare(`SELECT working_cefr FROM learner_profiles WHERE user_id='primary'`).first<{working_cefr:string}>();return c.json({unitStatusFunnel:states.results,reviews,speaking,transfer,errors,workingEstimate:profile?.working_cefr??'Baseline not completed',metricDefinitions:{activeRecallAccuracy:'Active-recall cards only, last 30 days',speakingMinutes:'Measured speaking sessions only, last 30 days',transferCount:'Distinct units with transfer evidence, last 30 days',recurrentErrors:'Feedback events observed in the last 30 days'}});});
api.get('/progress/timeseries',async(c)=>{const reviews=await c.env.DB.prepare(`SELECT substr(e.reviewed_at,1,10) date,ROUND(AVG(e.correct)*100,1) recallAccuracy,COUNT(*) reviews FROM review_events e JOIN review_cards c ON c.id=e.card_id WHERE c.card_type='active_recall' AND e.reviewed_at>=datetime('now','-90 days') GROUP BY date ORDER BY date`).all();const speaking=await c.env.DB.prepare(`SELECT substr(started_at,1,10) date,ROUND(SUM(duration_seconds)/60.0,1) minutes FROM practice_sessions WHERE session_type='speaking' AND started_at>=datetime('now','-90 days') GROUP BY date ORDER BY date`).all();const production=await c.env.DB.prepare(`SELECT substr(created_at,1,10) date,COUNT(DISTINCT unit_id) productive FROM learning_evidence WHERE dimension='production' AND score>=65 AND created_at>=datetime('now','-90 days') GROUP BY date ORDER BY date`).all();return c.json({reviews:reviews.results,speaking:speaking.results,production:production.results});});
api.get('/reports/weekly',async(c)=>{const rows=await c.env.DB.prepare('SELECT * FROM weekly_reports ORDER BY week_start DESC LIMIT 52').all();return c.json({reports:rows.results});});
api.post('/reports/weekly/generate',async(c)=>{const today=localDate(c.env.APP_TIMEZONE||'America/New_York');const endDate=new Date(`${today}T12:00:00Z`);endDate.setUTCDate(endDate.getUTCDate()+1);const weekEnd=endDate.toISOString().slice(0,10);const startDate=new Date(endDate);startDate.setUTCDate(startDate.getUTCDate()-7);const weekStart=startDate.toISOString().slice(0,10);const existing=await c.env.DB.prepare('SELECT id FROM weekly_reports WHERE user_id=? AND week_start=?').bind(SINGLE_USER_ID,weekStart).first<{id:string}>();if(existing)return c.json({status:'complete',id:existing.id});try{const instance=await c.env.WEEKLY_REPORT.create({id:`weekly-${weekStart}`,params:{weekStart,weekEnd}});return c.json({status:'processing',instanceId:instance.id,weekStart,weekEnd},202);}catch{return c.json({status:'processing',weekStart,weekEnd},202);}});
api.get('/reports/weekly/:id',async(c)=>{const row=await c.env.DB.prepare('SELECT * FROM weekly_reports WHERE id=?').bind(c.req.param('id')).first();return row?c.json(row):c.json({error:'Report not found'},404);});

api.post('/export',async(c)=>{
  const requested=await c.req.json().catch(()=>({format:'json'})) as {format?:unknown};
  const format=requested.format==='csv'||requested.format==='markdown'?requested.format:'json';
  const [profile,units,reviews,sessions,turns,assessments,assessmentItems,assessmentResponses,writings,captures,reports,evidence,retries,missions,plans,planItems,audio]=await Promise.all([
    c.env.DB.prepare(`SELECT u.*,p.* FROM users u JOIN learner_profiles p ON p.user_id=u.id WHERE u.id='primary'`).first(),
    c.env.DB.prepare(`SELECT u.term,u.unit_type,u.cefr,s.* FROM learning_units u JOIN user_unit_states s ON s.unit_id=u.id WHERE s.user_id='primary'`).all(),
    c.env.DB.prepare('SELECT * FROM review_events ORDER BY reviewed_at').all(),
    c.env.DB.prepare('SELECT * FROM practice_sessions ORDER BY started_at').all(),
    c.env.DB.prepare('SELECT * FROM practice_turns ORDER BY session_id,turn_index').all(),
    c.env.DB.prepare('SELECT * FROM assessments ORDER BY started_at').all(),
    c.env.DB.prepare('SELECT id,assessment_id,unit_id,section,ordinal,prompt,options_json,cefr FROM assessment_items ORDER BY assessment_id,ordinal').all(),
    c.env.DB.prepare('SELECT * FROM assessment_responses ORDER BY assessment_id,rowid').all(),
    c.env.DB.prepare('SELECT * FROM writing_submissions ORDER BY created_at').all(),
    c.env.DB.prepare('SELECT id,capture_type,redacted_text,context,audio_object_key,extracted_json,created_at FROM real_world_captures ORDER BY created_at').all(),
    c.env.DB.prepare('SELECT * FROM weekly_reports ORDER BY week_start').all(),
    c.env.DB.prepare('SELECT * FROM learning_evidence ORDER BY created_at').all(),
    c.env.DB.prepare('SELECT * FROM retry_attempts ORDER BY created_at').all(),
    c.env.DB.prepare('SELECT * FROM missions ORDER BY local_date').all(),
    c.env.DB.prepare('SELECT * FROM daily_plans ORDER BY local_date').all(),
    c.env.DB.prepare('SELECT * FROM daily_plan_items ORDER BY plan_id,sequence').all(),
    c.env.AUDIO_BUCKET.list({prefix:'audio/',limit:1000}),
  ]);
  const audioManifest=audio.objects.map((object)=>({key:object.key,size:object.size,uploaded:object.uploaded.toISOString(),downloadUrl:`/api/audio/${encodeURIComponent(object.key)}`}));
  let payload:string;let type:string;
  if(format==='csv'){const header='term,unit_type,cefr,status,recognition,recall,production,transfer';payload=[header,...units.results.map((u)=>[u.term,u.unit_type,u.cefr,u.status,u.recognition_score,u.recall_score,u.production_score,u.transfer_score].map((v)=>`"${String(v??'').replaceAll('"','""')}"`).join(','))].join('\n');type='text/csv';}
  else if(format==='markdown'){payload=`# Eric English OS — Weekly Reports\n\n${reports.results.map((r)=>`## ${String(r.week_start)} to ${String(r.week_end)}\n\n${String(r.narrative_json)}`).join('\n\n')}`;type='text/markdown';}
  else{payload=JSON.stringify({exportedAt:nowIso(),profile,units:units.results,reviews:reviews.results,sessions:sessions.results,turns:turns.results,assessments:assessments.results,assessmentItems:assessmentItems.results,assessmentResponses:assessmentResponses.results,writings:writings.results,captures:captures.results,reports:reports.results,evidence:evidence.results,retries:retries.results,missions:missions.results,plans:plans.results,planItems:planItems.results,audioManifest,audioManifestTruncated:audio.truncated},null,2);type='application/json';}
  const id=crypto.randomUUID();const key=`exports/${id}.${format==='markdown'?'md':format}`;
  await c.env.AUDIO_BUCKET.put(key,payload,{httpMetadata:{contentType:type,contentDisposition:`attachment; filename="eric-english-os.${format==='markdown'?'md':format}"`}});
  await c.env.DB.prepare(`INSERT INTO exports(id,user_id,format,object_key,expires_at) VALUES(?,'primary',?,?,datetime('now','+7 days'))`).bind(id,format,key).run();
  return c.json({id,format,downloadUrl:`/api/export/${id}`},201);
});
api.get('/export/:id',async(c)=>{const row=await c.env.DB.prepare('SELECT object_key FROM exports WHERE id=?').bind(c.req.param('id')).first<{object_key:string}>();if(!row)return c.json({error:'Export not found'},404);const object=await c.env.AUDIO_BUCKET.get(row.object_key);if(!object)return c.json({error:'Export object missing'},404);const headers=new Headers();object.writeHttpMetadata(headers);headers.set('cache-control','private,no-store');return new Response(object.body,{headers});});
api.post('/audio/delete-all',async(c)=>{parse(confirmationSchema,await c.req.json());let cursor:string|undefined;let deleted=0;do{const listed=await c.env.AUDIO_BUCKET.list({prefix:'audio/',cursor,limit:1000});const keys=listed.objects.map((object)=>object.key);if(keys.length){await c.env.AUDIO_BUCKET.delete(keys);deleted+=keys.length;}cursor=listed.truncated?listed.cursor:undefined;}while(cursor);await c.env.DB.batch([c.env.DB.prepare('UPDATE practice_turns SET audio_object_key=NULL'),c.env.DB.prepare('UPDATE assessment_responses SET audio_object_key=NULL'),c.env.DB.prepare('UPDATE real_world_captures SET audio_object_key=NULL'),c.env.DB.prepare('UPDATE retry_attempts SET audio_object_key=NULL')]);return c.json({deleted,recoverable:false});});
api.post('/data/delete-all',async(c)=>{parse(confirmationSchema,await c.req.json());let cursor:string|undefined;let deletedObjects=0;do{const listed=await c.env.AUDIO_BUCKET.list({cursor,limit:1000});const keys=listed.objects.map((object)=>object.key);if(keys.length){await c.env.AUDIO_BUCKET.delete(keys);deletedObjects+=keys.length;}cursor=listed.truncated?listed.cursor:undefined;}while(cursor);const tables=['realtime_events','retry_attempts','learning_evidence','review_events','review_cards','daily_plan_items','daily_plans','missions','practice_turns','practice_sessions','writing_submissions','feedback_items','error_patterns','real_world_captures','event_preps','assessment_responses','assessment_items','assessments','weekly_reports','personal_examples','ai_usage_events','job_runs','exports','api_rate_events','user_unit_states','learner_profiles','users'];for(const table of tables)await c.env.DB.prepare(`DELETE FROM ${table}`).run();await c.env.DB.batch([c.env.DB.prepare(`DELETE FROM learning_units WHERE source<>'seed'`),c.env.DB.prepare(`DELETE FROM scenarios WHERE source<>'seed'`)]);return c.json({deleted:true,deletedObjects,recoverableViaD1TimeTravel:true,needsBootstrap:true});});
